import Foundation
func resolvePointer(_ root: Any,_ pointer: String) -> Any? {if pointer.isEmpty{return root};guard pointer.first=="/" else{return nil};var current:Any=root;for raw in pointer.dropFirst().split(separator:"/",omittingEmptySubsequences:false){var token="";var it=raw.makeIterator();while let c=it.next(){if c=="~"{guard let n=it.next(),n=="0"||n=="1" else{return nil};token.append(n=="0" ? "~":"/")}else{token.append(c)}};if let object=current as? [String:Any]{guard let next=object[token]else{return nil};current=next}else if let array=current as? [Any]{guard !token.isEmpty,token=="0"||token.first != "0",token.allSatisfy({$0 >= "0" && $0 <= "9"}),let index=Int(token),index<array.count else{return nil};current=array[index]}else{return nil}};return current}
